-- ============================================================================
-- Hochwertige, einzeln verfasste CRA-Risikotexte (Fable, de+en) fuer alle 83
-- Kontrollen — ersetzt die maschinellen Echo-Texte ("Risiko bei Nichterfuellung
-- — <Frage>...") und ergaenzt fehlendes text_en. Idempotent (UPSERT).
-- ============================================================================
BEGIN;

ON CONFLICT (risk_id) DO UPDATE
  SET text_de=EXCLUDED.text_de, text_en=EXCLUDED.text_en;

ON CONFLICT (framework, control_id, risk_id) DO NOTHING;

COMMIT;
